text:
{
  "jobs": [
    {
      "text": "Регулярно созваниваться с пожилым отцом и поддерживать с ним связь",
      "quote": "А вот с папой почти каждый день по телефону разговариваем."
    },
    {
      "text": "Знать, что с отцом всё в порядке, и чтобы он знал, что с ней всё в порядке",
      "quote": "Я сначала сказала ему, что я на работе и со мной всё хорошо."
    },
    {
      "text": "Обеспечить отцу возможность дозвониться до неё или брата, если что-то случилось",
      "quote": "Вечером созвонились с моим братом и договорились, что, если папа не может до меня дозвониться, сразу набирает его."
    },
    {
      "text": "Защитить отца от мошеннических звонков, не мешая при этом обычным звонкам",
      "quote": "Теперь у нас одно правило на случай, если звонят якобы от меня и просят денег. Он кладёт трубку и сам набирает меня или брата."
    },
    {
      "text": "Оплачивать отцу полезные услуги на телефоне",
      "quote": "Из похожего я оплачиваю папе СМС от банка, около 70 рублей в месяц."
    }
  ],
  "pains": [
    {
      "text": "Отец сильно пугается, когда не может дозвониться до неё",
      "quote": "Оказалось, ему позвонили, он услышал женский плач и решил, что это я."
    },
    {
      "text": "Отец уже готов был ехать, не зная куда",
      "quote": "Папа ничего не перевёл, но, говорит, уже стоял в прихожей с ключами. Даже не знал, в какую больницу ехать."
    },
    {
      "text": "Пока никто из детей не ответил, отец может думать, что случилась беда",
      "quote": "Для меня это просто десять минут до перерыва, а папа все эти десять минут может думать, что со мной беда."
    },
    {
      "text": "Она не может ответить сразу, потому что работает у печи",
      "quote": "У печи я звонка не услышу, брат бывает за рулём."
    },
    {
      "text": "Отец может испугаться ещё сильнее, если разговор просто оборвётся",
      "quote": "Если разговор про «аварию» просто оборвётся, он ведь ещё сильнее испугается."
    }
  ],
  "current_solutions": [
    {
      "text": "Договорённость: если отец не может дозвониться до неё, звонит брату",
      "quote": "Вечером созвонились с моим братом и договорились, что, если папа не может до меня дозвониться, сразу набирает его."
    },
    {
      "text": "Избранные контакты у отца — дети",
      "quote": "Избранные контакты у папы теперь начинаются с нас двоих."
    },
    {
      "text": "Правило: при подозрительном звонке от имени дочери с просьбой о деньгах — положить трубку и самому набрать её или брата",
      "quote": "Теперь у нас одно правило на случай, если звонят якобы от меня и просят денег. Он кладёт трубку и сам набирает меня или брата."
    },
    {
      "text": "Оплата СМС от банка для отца",
      "quote": "Из похожего я оплачиваю папе СМС от банка, около 70 рублей в месяц."
    }
  ],
  "barriers": [
    {
      "text": "Барьер понимания: неясно, работает ли сервис на кнопочном телефоне",
      "quote": "Мне сразу хочется уточнить, работает ли это на кнопочном телефоне."
    },
    {
      "text": "Барьер понимания: важно, что услышит сам отец при блокировке звонка",
      "quote": "И ещё важно, что услышит сам папа."
    },
    {
      "text": "Барьер выбора: отец может отказаться, если начнут пропадать обычные звонки",
      "quote": "Если начнут пропадать звонки, он попросит всё отключить."
    },
    {
      "text": "Барьер выбора: куда придёт уведомление — СМС предпочтительнее приложения",
      "quote": "А мне важно, куда придёт уве[АДРЕС]. СМС я увижу на первом же перерыве, а в отдельное приложение могу два дня не заглядывать."
    },
    {
      "text": "Барьер оплаты: готовность платить обусловлена работоспособностью на телефоне отца",
      "quote": "За защиту от звонков я бы так же спокойно добавила к его тарифу рублей 80 в месяц, если на его телефоне всё заработает."
    }
  ],
  "triggers": [
    {
      "text": "Мошеннический звонок отцу с имитацией плача дочери и сообщением об аварии",
      "quote": "Оказалось, ему позвонили, он услышал женский плач и решил, что это я. Потом какой-то мужчина сказал, что я попала в аварию и нужны деньги."
    },
    {
      "text": "Отец уже стоял в прихожей с ключами, готовый ехать",
      "quote": "Папа ничего не перевёл, но, говорит, уже стоял в прихожей с ключами."
    },
    {
      "text": "Просьба отца поговорить ещё минутку показала, как он испугался",
      "quote": "А он попросил: «Ты ещё минутку поговори»."
    }
  ],
  "words": [
    "«[имя], ты цела?»",
    "«Ты ещё минутку поговори»",
    "«стоял в прихожей с ключами»",
    "«до меня дошло, как он испугался»",
    "«одно правило»",
    "«Избранные контакты»",
    "«кнопочный телефон»",
    "«у печи я звонка не услышу»",
    "«десять минут»",
    "«если на его телефоне всё заработает»",
    "«спокойно добавила к его тарифу рублей 80 в месяц»"
  ],
  "surprises": [
    {
      "text": "Отец не перевёл деньги, но уже был готов ехать, не зная куда",
      "quote": "Папа ничего не перевёл, но, говорит, уже стоял в прихожей с ключами. Даже не знал, в какую больницу ехать."
    },
    {
      "text": "Отец сам просил пропускать звонки с незнакомых номеров, но это привело к пропуску важных звонков покупателей",
      "quote": "Он один раз так и сделал, а потом выяснилось, что это люди за мё[АДРЕС]и полчаса простояли у калитки."
    },
    {
      "text": "Отец сам попросил вернуть отключённые СМС от банка",
      "quote": "Мы как-то их отключили, а он через неделю попросил вернуть."
    }
  ]
}
